I'll implement a fetch using the ORCID public API works endpoint and include basic de-duplication via the group/work-summary structure. Public endpoints should be sufficient.

Plan:
- GET https://pub.orcid.org/v3.0/{ORCID}/works with Accept: application/json.
- Iterate groups -> work-summary -> publication-date.year.
- Count year < 2020; skip missing years.
- If the JSON endpoint fails, lightly fallback to parsing the public profile HTML to salvage visible years.

Python code:
```python
import requests, re
from bs4 import BeautifulSoup

orcid_list = [
    '0000-0001-6102-7846',
    '0000-0002-0209-2784',
    '0000-0002-1053-2030',
    '0000-0002-2605-6569',
    '0000-0003-0396-0333'
]

session = requests.Session()
headers = {'Accept': 'application/json'}

def count_pre2020(orcid):
    url = f'https://pub.orcid.org/v3.0/{orcid}/works'
    try:
        r = session.get(url, headers=headers, timeout=8)
        if r.status_code == 200:
            data = r.json()
            c = 0
            for grp in data.get('group', []):
                for ws in grp.get('work-summary', []):
                    pd = ws.get('publication-date') or {}
                    y = (pd.get('year') or {}).get('value')
                    if y and y.isdigit() and int(y) < 2020:
                        c += 1
            return c
        else:
            # Fallback to HTML scraping
            html = session.get(f'https://orcid.org/{orcid}', timeout=8).text
            soup = BeautifulSoup(html, 'html.parser')
            years = []
            for tag in soup.find_all(text=re.compile(r'\b(19\d{2}|20\d{2})\b')):
                m = re.search(r'\b(19\d{2}|20\d{2})\b', tag)
                if m:
                    y = int(m.group(1))
                    years.append(y)
            return sum(1 for y in years if y < 2020)
    except Exception as e:
        print(f"Fetch error for {orcid}: {e}")
        return 0

results = {}
for oid in orcid_list:
    results[oid] = count_pre2020(oid)
print(results)
```
